"use client"

import "@astryxdesign/core/reset.css"
import "@astryxdesign/core/astryx.css"
import "@astryxdesign/theme-neutral/theme.css"
import { AvatarGroupOverflow } from "@astryxdesign/core/AvatarGroup"

function restoreAstryxLayerPriority() {
  if (typeof document === "undefined" || document.getElementById("astryx-unlayered-compat")) return
  const wanted = new Set(["astryx-base", "astryx-theme"])
  let css = ""
  for (const sheet of Array.from(document.styleSheets)) {
    try {
      for (const rule of Array.from(sheet.cssRules)) {
        const layer = rule as CSSRule & { name?: string; cssRules?: CSSRuleList }
        if (layer.name && layer.cssRules && wanted.has(layer.name)) {
          css += Array.from(layer.cssRules, (child) => child.cssText).join("\n")
        }
      }
    } catch {}
  }
  if (css) {
    const style = document.createElement("style")
    style.id = "astryx-unlayered-compat"
    style.textContent = css
    document.head.append(style)
  }
}

restoreAstryxLayerPriority()

export * from "@astryxdesign/core/AvatarGroup"
export default AvatarGroupOverflow
